// ──────────────────────────── tests ──────────────────────────────────────

test('a stub returns the same value on every call', () => {
  const getRate = stub(1.25);
  eq(getRate('EUR'), 1.25);
  eq(getRate(), 1.25);
});

test('a stub records the arguments of every call', () => {
  const getRate = stub(1);
  getRate('EUR', 2);
  getRate('GBP');
  eq(getRate.calls, [['EUR', 2], ['GBP']]);
  eq(getRate.callCount, 2);
});

test('lastCall is undefined until the double is called', () => {
  const getRate = stub(1);
  eq(getRate.lastCall, undefined);
  getRate('EUR');
  getRate('GBP');
  eq(getRate.lastCall, ['GBP']);
});

test('calledWith compares arguments deeply, not by reference', () => {
  const save = stub(true);
  save({ id: 1, tags: ['a'] });
  ok(save.calledWith({ id: 1, tags: ['a'] }));
  ok(!save.calledWith({ id: 2, tags: ['a'] }));
  ok(!save.calledWith());
});

test('a fake delegates to the implementation', () => {
  const add = fake((a, b) => a + b);
  eq(add(2, 3), 5);
  eq(add.calls, [[2, 3]]);
});

test('a fake records what the implementation returned', () => {
  const add = fake((a, b) => a + b);
  add(1, 1);
  add(2, 2);
  eq(add.results, [
    { type: 'return', value: 2 },
    { type: 'return', value: 4 },
  ]);
});

test('a fake records a throw and still re-throws it', () => {
  const send = fake((to) => {
    if (!to) throw new Error('no recipient');
    return 'sent';
  });
  send('a@b.c');
  throws(() => send(''), 'no recipient');
  eq(send.callCount, 2);
  eq(send.results[0], { type: 'return', value: 'sent' });
  eq(send.results[1].type, 'throw');
  eq(send.results[1].value.message, 'no recipient');
});

test('two doubles never share their recordings', () => {
  const a = stub(1);
  const b = stub(1);
  a('x');
  eq(a.callCount, 1);
  eq(b.callCount, 0);
  eq(b.calls, []);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('the spy calls through to the original by default', () => {
  const api = { double: (n) => n * 2 };
  const s = spyOn(api, 'double');
  eq(api.double(21), 42);
  eq(s.callCount, 1);
});

test('the spy records arguments and return values', () => {
  const api = { double: (n) => n * 2 };
  const s = spyOn(api, 'double');
  api.double(1);
  api.double(5);
  eq(s.calls, [[1], [5]]);
  eq(s.returns, [2, 10]);
});

test('`this` is still the object the method was called on', () => {
  const counter = {
    count: 0,
    bump(n) {
      this.count += n;
      return this.count;
    },
  };
  spyOn(counter, 'bump');
  eq(counter.bump(2), 2);
  eq(counter.bump(3), 5);
  eq(counter.count, 5);
});

test('restore puts the exact original function back', () => {
  const double = (n) => n * 2;
  const api = { double };
  const s = spyOn(api, 'double');
  ok(api.double !== double, 'the method should be patched while spying');
  s.restore();
  ok(api.double === double, 'restore should put the original back');
});

test('restoring an inherited method leaves no own property behind', () => {
  const proto = {
    greet() {
      return 'hi';
    },
  };
  const obj = Object.create(proto);
  const s = spyOn(obj, 'greet');
  eq(obj.greet(), 'hi');
  s.restore();
  eq(Object.hasOwn(obj, 'greet'), false);
  eq(obj.greet(), 'hi');
});

test('a replacement implementation runs instead of the original', () => {
  let realRan = false;
  const api = {
    save() {
      realRan = true;
      return 'real';
    },
  };
  const s = spyOn(api, 'save', () => 'stubbed');
  eq(api.save(), 'stubbed');
  eq(realRan, false);
  eq(s.callCount, 1);
});

test('calls made after restore are not recorded', () => {
  const api = { double: (n) => n * 2 };
  const s = spyOn(api, 'double');
  api.double(1);
  s.restore();
  api.double(2);
  eq(s.callCount, 1);
});

test('restore twice is harmless, and spying on a non-method throws', () => {
  const api = { double: (n) => n * 2, version: '1.0' };
  const s = spyOn(api, 'double');
  s.restore();
  s.restore();
  eq(api.double(4), 8);
  throws(() => spyOn(api, 'version'));
});

// ──────────────────────────── tests ──────────────────────────────────────

test('makeCounter yields consecutive numbers from its start', () => {
  const next = makeCounter(10);
  eq([next(), next(), next()], [10, 11, 12]);
  eq(makeCounter()(), 1);
});

test('builds a complete user from the defaults', () => {
  const nextId = makeCounter(1);
  eq(makeUser({}, nextId), {
    id: 1,
    name: 'User 1',
    email: 'user1@example.test',
    active: true,
    address: { city: 'Springfield', zip: '00000', country: 'US' },
    roles: ['viewer'],
  });
});

test('each call takes a fresh id from the counter', () => {
  const nextId = makeCounter(1);
  const a = makeUser({}, nextId);
  const b = makeUser({}, nextId);
  eq([a.id, b.id], [1, 2]);
  eq(b.email, 'user2@example.test');
});

test('a top-level override wins over the default', () => {
  const nextId = makeCounter(1);
  const user = makeUser({ active: false, name: 'Ada' }, nextId);
  eq(user.active, false);
  eq(user.name, 'Ada');
  eq(user.email, 'user1@example.test');
});

test('an explicit id override drives the derived fields', () => {
  const nextId = makeCounter(1);
  const user = makeUser({ id: 42 }, nextId);
  eq(user.id, 42);
  eq(user.name, 'User 42');
  eq(user.email, 'user42@example.test');
});

test('a nested address override keeps the other address defaults', () => {
  const nextId = makeCounter(1);
  const user = makeUser({ address: { city: 'Oslo' } }, nextId);
  eq(user.address, { city: 'Oslo', zip: '00000', country: 'US' });
});

test('arrays are replaced, not merged', () => {
  const nextId = makeCounter(1);
  eq(makeUser({ roles: ['admin'] }, nextId).roles, ['admin']);
});

test('two users never share the same nested address object', () => {
  const nextId = makeCounter(1);
  const a = makeUser({}, nextId);
  const b = makeUser({}, nextId);
  ok(a.address !== b.address, 'each user needs its own address object');
  a.address.city = 'Mutated';
  eq(b.address.city, 'Springfield');
});

// ──────────────────────────── tests ──────────────────────────────────────

const DEFAULTS = { name: 'Ada', role: 'viewer', teamId: 7 };

test('build() returns the defaults', () => {
  const aUser = builder(DEFAULTS);
  eq(aUser().build(), { name: 'Ada', role: 'viewer', teamId: 7 });
});

test('there is one setter per default key, and no others', () => {
  const aUser = builder(DEFAULTS);
  const b = aUser();
  eq(typeof b.withName, 'function');
  eq(typeof b.withRole, 'function');
  eq(typeof b.withTeamId, 'function');
  eq(b.withNope, undefined);
});

test('a setter sets its field and leaves the rest alone', () => {
  const aUser = builder(DEFAULTS);
  eq(aUser().withName('Bo').build(), {
    name: 'Bo',
    role: 'viewer',
    teamId: 7,
  });
});

test('setters chain', () => {
  const aUser = builder(DEFAULTS);
  eq(aUser().withName('Bo').withRole('admin').withTeamId(1).build(), {
    name: 'Bo',
    role: 'admin',
    teamId: 1,
  });
});

test('with(patch) applies several keys at once', () => {
  const aUser = builder(DEFAULTS);
  eq(aUser().with({ role: 'admin', teamId: 2 }).build(), {
    name: 'Ada',
    role: 'admin',
    teamId: 2,
  });
});

test('every setter returns a NEW builder — the base is untouched', () => {
  const aUser = builder(DEFAULTS);
  const base = aUser();
  const admin = base.withRole('admin');
  ok(admin !== base, 'a setter must not return the same builder');
  eq(admin.build().role, 'admin');
  eq(base.build().role, 'viewer');
});

test('build() hands out a fresh object every time', () => {
  const aUser = builder(DEFAULTS);
  const b = aUser();
  const first = b.build();
  first.name = 'Mutated';
  eq(b.build().name, 'Ada');
});

test('the defaults object itself is never modified', () => {
  const defaults = { name: 'Ada', role: 'viewer', teamId: 7 };
  const aUser = builder(defaults);
  aUser().withName('Bo').withRole('admin').build();
  eq(defaults, { name: 'Ada', role: 'viewer', teamId: 7 });
});

// ──────────────────────────── tests ──────────────────────────────────────

test('a fake clock starts where you put it and does not drift', () => {
  const clock = makeFakeClock(1000);
  eq(clock.now(), 1000);
  eq(clock.now(), 1000);
});

test('advance moves time forward and returns the new now', () => {
  const clock = makeFakeClock(0);
  eq(clock.advance(500), 500);
  eq(clock.advance(500), 1000);
  eq(clock.now(), 1000);
});

test('sleep advances the clock and resolves without real waiting', async () => {
  const clock = makeFakeClock(0);
  const order = [];
  const done = clock.sleep(60_000).then(() => order.push('slept'));
  order.push('sync');
  await done;
  eq(order, ['sync', 'slept']);
  eq(clock.now(), 60_000);
});

test('a fresh timer is not expired and has the whole timeout left', () => {
  const clock = makeFakeClock(5000);
  const session = createSessionTimer(clock, 30_000);
  eq(session.isExpired(), false);
  eq(session.idleMs(), 0);
  eq(session.remainingMs(), 30_000);
});

test('the timer expires exactly AT the timeout, not a tick later', () => {
  const clock = makeFakeClock(0);
  const session = createSessionTimer(clock, 30_000);
  clock.advance(29_999);
  eq(session.isExpired(), false);
  clock.advance(1);
  eq(session.isExpired(), true);
});

test('touch restarts the countdown', () => {
  const clock = makeFakeClock(0);
  const session = createSessionTimer(clock, 30_000);
  clock.advance(29_000);
  session.touch();
  clock.advance(29_000);
  eq(session.isExpired(), false);
  eq(session.remainingMs(), 1000);
});

test('remainingMs clamps at zero instead of going negative', () => {
  const clock = makeFakeClock(0);
  const session = createSessionTimer(clock, 1000);
  clock.advance(10_000);
  eq(session.remainingMs(), 0);
  eq(session.idleMs(), 10_000);
});

test('two timers share one clock without interfering', () => {
  const clock = makeFakeClock(0);
  const short = createSessionTimer(clock, 1000);
  const long = createSessionTimer(clock, 60_000);
  clock.advance(2000);
  eq(short.isExpired(), true);
  eq(long.isExpired(), false);
  short.touch();
  eq(short.isExpired(), false);
  eq(long.idleMs(), 2000);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('scheduling runs nothing, and pending() counts what is waiting', () => {
  const s = createFakeScheduler();
  const calls = [];
  s.setTimeout(() => calls.push('a'), 10);
  s.setTimeout(() => calls.push('b'), 20);
  eq(calls, []);
  eq(s.pending(), 2);
  eq(s.now(), 0);
  s.advance(10);
  eq(calls, ['a']);
  eq(s.pending(), 1);
});

test('advance runs the due callback and moves now', () => {
  const s = createFakeScheduler();
  let ranAt = null;
  s.setTimeout(() => {
    ranAt = s.now();
  }, 30);
  eq(s.advance(100), 100);
  eq(ranAt, 30);
  eq(s.now(), 100);
});

test('callbacks fire in due order, not registration order', () => {
  const s = createFakeScheduler();
  const order = [];
  s.setTimeout(() => order.push('late'), 100);
  s.setTimeout(() => order.push('early'), 10);
  s.setTimeout(() => order.push('mid'), 50);
  s.advance(100);
  eq(order, ['early', 'mid', 'late']);
});

test('clearTimeout stops a pending timer', () => {
  const s = createFakeScheduler();
  const calls = [];
  const id = s.setTimeout(() => calls.push('never'), 10);
  s.setTimeout(() => calls.push('yes'), 10);
  s.clearTimeout(id);
  eq(s.pending(), 1);
  s.runAll();
  eq(calls, ['yes']);
});

test('a timer scheduled inside a callback runs in the same window', () => {
  const s = createFakeScheduler();
  const order = [];
  s.setTimeout(() => {
    order.push('outer');
    s.setTimeout(() => order.push('inner'), 10);
  }, 20);
  s.advance(50);
  eq(order, ['outer', 'inner']);
  eq(s.pending(), 0);
  eq(s.now(), 50);
});

test('runAll drains a chain of nested timers, and refuses a runaway', () => {
  const s = createFakeScheduler();
  const order = [];
  const chain = (n) => {
    if (n === 0) return;
    s.setTimeout(() => {
      order.push(n);
      chain(n - 1);
    }, 1000);
  };
  chain(3);
  eq(s.runAll(), 3000);
  eq(order, [3, 2, 1]);

  const runaway = createFakeScheduler();
  const forever = () => runaway.setTimeout(forever, 0);
  forever();
  throws(() => runaway.runAll());
});

test('debounce fires once, with the latest arguments', () => {
  const s = createFakeScheduler();
  const calls = [];
  const save = debounce((value) => calls.push(value), 100, s);
  save('a');
  save('b');
  save('c');
  eq(s.pending(), 1);
  s.advance(99);
  eq(calls, []);
  s.advance(1);
  eq(calls, ['c']);
  eq(s.pending(), 0);
});

test('every call restarts the debounce countdown', () => {
  const s = createFakeScheduler();
  const calls = [];
  const save = debounce((value) => calls.push(value), 100, s);
  save('a');
  s.advance(90);
  save('b');
  s.advance(90);
  eq(calls, []);
  s.advance(10);
  eq(calls, ['b']);
});

// ──────────────────────────── tests ──────────────────────────────────────

test('next() returns floats in [0, 1)', () => {
  const rng = makeRandom(42);
  for (let i = 0; i < 200; i++) {
    const v = rng.next();
    ok(typeof v === 'number' && v >= 0 && v < 1, `out of range: ${v}`);
  }
});

test('the same seed replays the same sequence', () => {
  const a = makeRandom(7);
  const b = makeRandom(7);
  const first = Array.from({ length: 8 }, () => a.next());
  const second = Array.from({ length: 8 }, () => b.next());
  eq(first, second);
  ok(new Set(first).size > 1, 'the sequence should not be constant');
});

test('different seeds give different sequences', () => {
  const a = makeRandom(1);
  const b = makeRandom(2);
  const left = Array.from({ length: 5 }, () => a.next());
  const right = Array.from({ length: 5 }, () => b.next());
  ok(left.some((v, i) => v !== right[i]), 'seeds 1 and 2 should differ');
});

test('int(min, max) stays in range and reaches both ends', () => {
  const rng = makeRandom(99);
  const seen = new Set();
  for (let i = 0; i < 500; i++) {
    const v = rng.int(1, 6);
    ok(Number.isInteger(v) && v >= 1 && v <= 6, `out of range: ${v}`);
    seen.add(v);
  }
  eq([...seen].sort(), [1, 2, 3, 4, 5, 6]);
});

test('int(n, n) is always n', () => {
  const rng = makeRandom(3);
  eq(Array.from({ length: 10 }, () => rng.int(5, 5)), Array(10).fill(5));
});

test('pick returns an element, and the same seed picks the same one', () => {
  const colours = ['red', 'green', 'blue', 'gold'];
  const a = makeRandom(12);
  const b = makeRandom(12);
  const picks = Array.from({ length: 6 }, () => a.pick(colours));
  eq(picks, Array.from({ length: 6 }, () => b.pick(colours)));
  ok(picks.every((p) => colours.includes(p)), 'every pick must be a colour');
});

test('shuffle returns a new array and leaves the input alone', () => {
  const deck = Array.from({ length: 20 }, (_, i) => i);
  const before = [...deck];
  const out = makeRandom(5).shuffle(deck);
  ok(out !== deck, 'shuffle must not return the same array');
  eq(deck, before);
  eq([...out].sort((x, y) => x - y), before);
});

test('the same seed gives the same permutation — and it really moves', () => {
  const deck = Array.from({ length: 30 }, (_, i) => i);
  const a = makeRandom(2024).shuffle(deck);
  const b = makeRandom(2024).shuffle(deck);
  eq(a, b);
  ok(a.some((v, i) => v !== deck[i]), 'a shuffle should reorder something');
});

// ──────────────────────────── tests ──────────────────────────────────────

test('flushPromises lets already-queued microtasks run first', async () => {
  const order = [];
  Promise.resolve()
    .then(() => order.push('micro'))
    .then(() => order.push('chained'));
  order.push('sync');
  await flushPromises();
  eq(order, ['sync', 'micro', 'chained']);
});

test('the queue starts only up to the concurrency limit', async () => {
  const q = createQueue(2);
  const gates = [deferred(), deferred(), deferred()];
  const started = [];
  gates.forEach((g, i) =>
    q.add(() => {
      started.push(i);
      return g.promise;
    })
  );
  await flushPromises();
  eq(started, [0, 1]);
  eq(q.stats(), { running: 2, queued: 1, done: 0 });
  gates.forEach((g) => g.resolve());
});

test('finishing one task starts exactly one waiting task', async () => {
  const q = createQueue(2);
  const gates = [deferred(), deferred(), deferred(), deferred()];
  const started = [];
  gates.forEach((g, i) =>
    q.add(() => {
      started.push(i);
      return g.promise;
    })
  );
  await flushPromises();
  gates[0].resolve();
  await flushPromises();
  eq(started, [0, 1, 2]);
  eq(q.stats(), { running: 2, queued: 1, done: 1 });
  gates.forEach((g) => g.resolve());
});

test('with concurrency 1 the queue is a strict pipeline', async () => {
  const q = createQueue(1);
  const gates = [deferred(), deferred(), deferred()];
  const started = [];
  gates.forEach((g, i) =>
    q.add(() => {
      started.push(i);
      return g.promise;
    })
  );
  await flushPromises();
  eq(started, [0]);
  gates[0].resolve();
  await flushPromises();
  eq(started, [0, 1]);
  gates[1].resolve();
  await flushPromises();
  eq(started, [0, 1, 2]);
  gates[2].resolve();
});

test('add() resolves with the task result', async () => {
  const q = createQueue(2);
  eq(await q.add(async () => 42), 42);
  eq(await q.add(() => 'sync values work too'), 'sync values work too');
});

test('a failing task rejects its own promise and nothing else', async () => {
  const q = createQueue(1);
  await rejects(
    q.add(async () => {
      throw new Error('boom');
    }),
    'boom'
  );
  eq(await q.add(async () => 'still working'), 'still working');
});

test('a failure does not wedge the pump', async () => {
  const q = createQueue(1);
  const results = await Promise.allSettled([
    q.add(async () => {
      throw new Error('one');
    }),
    q.add(async () => 'two'),
    q.add(async () => 'three'),
  ]);
  eq(results.map((r) => r.status), ['rejected', 'fulfilled', 'fulfilled']);
  eq(q.stats(), { running: 0, queued: 0, done: 3 });
});

test('the queue drains back to zero and keeps results in add order', async () => {
  const q = createQueue(2);
  const out = await Promise.all(
    [1, 2, 3, 4, 5].map((n) => q.add(async () => n * 2))
  );
  eq(out, [2, 4, 6, 8, 10]);
  eq(q.stats(), { running: 0, queued: 0, done: 5 });
});

// ──────────────────────────── tests ──────────────────────────────────────

test('branchesHit names the branch one order takes', () => {
  eq(branchesHit([{ total: 150, weightKg: 1, express: false }]), ['free']);
  eq(branchesHit([{ total: 10, weightKg: 1, express: false }]), ['standard']);
});

test('branchesHit dedupes and sorts', () => {
  const small = { total: 10, weightKg: 1, express: false };
  const heavy = { total: 10, weightKg: 30, express: false };
  eq(branchesHit([small, heavy, small]), ['heavy', 'standard']);
});

test('the first matching rule wins — free beats express and heavy', () => {
  eq(branchesHit([{ total: 500, weightKg: 99, express: true }]), ['free']);
  eq(branchesHit([{ total: 50, weightKg: 99, express: true }]), ['express']);
});

test('minimalInputs covers every branch', () => {
  eq(branchesHit(minimalInputs()), ALL_BRANCHES);
});

test('minimalInputs uses exactly one order per branch', () => {
  eq(minimalInputs().length, ALL_BRANCHES.length);
});

test('no input is redundant — dropping any one loses coverage', () => {
  const inputs = minimalInputs();
  inputs.forEach((_, i) => {
    const without = inputs.filter((_, j) => j !== i);
    const covered = branchesHit(without);
    ok(
      covered.length < ALL_BRANCHES.length,
      `input ${i} is redundant: coverage stayed at ${covered.join(',')}`
    );
  });
});

test('every input is a well-formed order', () => {
  for (const order of minimalInputs()) {
    ok(typeof order.total === 'number', 'total must be a number');
    ok(typeof order.weightKg === 'number', 'weightKg must be a number');
    ok(typeof order.express === 'boolean', 'express must be a boolean');
  }
});

test('each input produces the cost of the branch it exercises', () => {
  for (const order of minimalInputs()) {
    const { cost, branches } = recordBranches(order);
    eq(branches.length, 1);
    eq(cost, COST_OF[branches[0]]);
  }
});

// ──────────────────────────── tests ──────────────────────────────────────

test('exactly equal numbers pass quietly', () => {
  eq(messageFrom(() => expectClose(3, 3)), null);
  eq(messageFrom(() => expectClose(-0.5, -0.5, 0)), null);
});

test('float noise inside the default tolerance passes', () => {
  eq(messageFrom(() => expectClose(0.1 + 0.2, 0.3)), null);
});

test('a real difference throws', () => {
  ok(messageFrom(() => expectClose(3.2, 3, 0.1)) !== null);
  ok(messageFrom(() => expectClose(0.1 + 0.2, 0.3, 0)) !== null);
});

test('the message names both values, the tolerance and the miss', () => {
  eq(
    messageFrom(() => expectClose(0.5, 0.25, 0.1)),
    'expected 0.5 to be within 0.1 of 0.25 (off by 0.25)'
  );
});

test('the tolerance is inclusive at the boundary', () => {
  eq(messageFrom(() => expectClose(1.5, 1, 0.5)), null);
  ok(messageFrom(() => expectClose(1.6, 1, 0.5)) !== null);
});

test('NaN is never close to anything, not even to NaN', () => {
  ok(messageFrom(() => expectClose(NaN, NaN, 10)) !== null);
  ok(messageFrom(() => expectClose(NaN, 1, 10)) !== null);
  ok(messageFrom(() => expectClose(1, NaN, 10)) !== null);
});

test('Infinity is close to itself but not to a finite number', () => {
  eq(messageFrom(() => expectClose(Infinity, Infinity)), null);
  ok(messageFrom(() => expectClose(Infinity, 1e308)) !== null);
});

test('a non-number is rejected with a type message', () => {
  eq(messageFrom(() => expectClose('3', 3)), 'expected a number, got string');
  eq(messageFrom(() => expectClose(3, null)), 'expected a number, got object');
  eq(
    messageFrom(() => expectClose(undefined, 3)),
    'expected a number, got undefined'
  );
});

// ──────────────────────────── tests ──────────────────────────────────────

test('a matching flat object passes', () => {
  const shape = { id: 'number', name: 'string', active: 'boolean' };
  eq(
    messageFrom(() =>
