test('shrinkInt walks toward zero and never offers n itself', () => {
  eq(shrinkInt(10), [0, 5, 9]);
  eq(shrinkInt(2), [0, 1]);
  eq(shrinkInt(1), [0]);
  eq(shrinkInt(0), []);
  eq(shrinkInt(-4), [0, -2, -3]);
});

test('shrinkArray drops one element at a time, in index order', () => {
  eq(shrinkArray([1, 2, 3]), [
    [2, 3],
    [1, 3],
    [1, 2],
  ]);
