  withTempDir((dir) => {
    snapshotTest('card', { title: 'Hi' }, { dir });
    const result = snapshotTest('card', { title: 'Bye' }, { dir });
    eq(result.status, 'mismatch');
    eq(result.expected, '{\n  "title": "Hi"\n}\n');
    eq(result.actual, '{\n  "title": "Bye"\n}\n');
  });
});

