    snapshotTest('card', { title: 'Hi' }, { dir });
    const env = { UPDATE_SNAPSHOTS: '1' };
    const updated = snapshotTest('card', { title: 'Bye' }, { dir, env });
    eq(updated.status, 'updated');
    eq(readFileSync(updated.path, 'utf8'), '{\n  "title": "Bye"\n}\n');
