    id: 1,
    name: 'User 1',
    email: 'user1@example.test',
    active: true,
    address: { city: 'Springfield', zip: '00000', country: 'US' },
    roles: ['viewer'],
  });
});

test('each call takes a fresh id from the counter', () => {
